# Browserprüfung für Ortskenntnisse und ihre Gültigkeit.
"""Location editor, real DS100 picker, sorting/filtering, German dates and expiry colours."""
import argparse
from browser_realtime import check_pages
from check_work_report_layout import STATIC

def fixture():
    scripts='\n'.join((STATIC/name).read_text() for name in ['messages.js','station-picker.js','location-editor.js','knowledge-inventory.js'])
    checks=r'''
(async()=>{const assert=(ok,msg)=>{if(!ok)throw Error(msg);},api=LocationKnowledgeEditor,day=api.today(),max=api.months(day,12),yesterday=new Date(Date.parse(day+'T00:00:00Z')-86400000).toISOString().slice(0,10),identity={owner_id:7,tf_number:'787100',first_name:'Mira',last_name:'Beispiel'};let online=true,adds=0,updates=0;Object.defineProperty(navigator,'onLine',{get:()=>online});const rows=[{id:1,station_name:'Berlin Z',ds100:'BBB',known_until:yesterday,revision:'a'.repeat(64)},{id:2,station_name:'Alpha',ds100:'AAA',known_until:api.months(day,2),revision:'b'.repeat(64)},{id:3,station_name:'Frankfurt',ds100:'CCC',known_until:api.months(day,6),revision:'c'.repeat(64)}];
window.StationCatalog={frequent:async()=>[],search:async query=>[{code:'AAA',name:'Alpha'},{code:'DDD',name:'Dresden'}].filter(r=>r.code.startsWith(query))};
window.fetch=async(url,options={})=>{if(!online)throw Error('Offline');let data={identity};if(options.method==='POST'){adds++;const body=JSON.parse(options.body);assert(body.ds100==='DDD'&&body.known_until<=max,'New DS100 and bounded date');rows.push({id:4,station_name:'Dresden',ds100:'DDD',known_until:body.known_until,revision:'d'.repeat(64)});}else if(options.method==='PATCH'){updates++;const body=JSON.parse(options.body);assert(body.expected_revision==='a'.repeat(64)&&body.known_until===max,'Renewal protects revision and cap');rows[0].known_until=body.known_until;rows[0].revision='e'.repeat(64);}else data={identity,items:structuredClone(rows),date_limits:{today:day,max_until:max,warning_until:api.months(day,3)}};return {ok:true,status:200,json:async()=>data};};
const root=document.getElementById('inventory');await KnowledgeInventory.mount({id:7},root,'places');const saved=root.querySelector('[data-knowledge-saved]'),form=root.querySelector('form'),file=root.querySelector('[data-knowledge-file]'),date=root.querySelector('[data-location-date]'),station=root.querySelector('[data-location-search]'),search=root.querySelector('[data-knowledge-search]');assert(form.compareDocumentPosition(saved)&Node.DOCUMENT_POSITION_FOLLOWING,'Editor above inventory');assert(saved.compareDocumentPosition(file)&Node.DOCUMENT_POSITION_FOLLOWING,'CSV import below inventory');assert(saved.querySelector('[data-location-state=expired]')&&saved.querySelector('[data-location-state=expiring]'),'Expired red and near-expiry orange states');assert(getComputedStyle(saved.querySelector('[data-location-state=expired] td')).backgroundColor==='rgb(255, 226, 226)','Expired cells are visibly red');assert(saved.textContent.includes(api.format(yesterday))&&!saved.textContent.includes(yesterday),'Dates shown as DD.MM.YYYY');
let button=saved.querySelector('[data-knowledge-sort=station_name]');button.click();assert(saved.querySelector('tbody tr').textContent.includes('Alpha'),'Ascending station sort');saved.querySelector('[data-knowledge-sort=station_name]').click();assert(saved.querySelector('tbody tr').textContent.includes('Frankfurt'),'Descending station sort');saved.querySelector('[data-knowledge-sort=known_until]').click();assert(saved.querySelector('tbody tr').textContent.includes('Berlin Z'),'Date sorting is chronological');saved.querySelector('[data-knowledge-sort=known_until]').click();assert(saved.querySelector('tbody tr').textContent.includes('Frankfurt'),'Reverse date sorting');
search.value='bbb';search.dispatchEvent(new Event('input'));assert(saved.querySelectorAll('tbody tr').length===1,'DS100 filter');saved.querySelector('tbody tr').click();assert(station.disabled&&station.value.includes('BBB'),'Existing station locked during date renewal');assert(date.max===max,'Maximum one calendar year');date.value=max;await form.onsubmit({preventDefault(){}});assert(updates===1&&rows[0].known_until===max,'Manual extension saved');root.querySelector('[data-location-reset]').click();
async function choose(code){station.focus();station.value=code;station.dispatchEvent(new Event('input',{bubbles:true}));await new Promise(r=>setTimeout(r,280));const option=document.querySelector('.station-picker [role=option]');assert(option,'Real DS100 dropdown visible');option.click();}
await choose('AAA');date.value=max;await form.onsubmit({preventDefault(){}});assert(adds===0,'Existing location cannot be added twice');root.querySelector('[data-location-reset]').click();await choose('DDD');date.value=max;await form.onsubmit({preventDefault(){}});assert(adds===1&&rows.length===4,'New DS100 location added');search.value='dresden';search.dispatchEvent(new Event('input'));assert(saved.querySelectorAll('tbody tr').length===1,'Place-name filter');search.value='';search.dispatchEvent(new Event('input'));assert(saved.querySelectorAll('tbody tr').length===4,'Clearing filter restores full list');
const orange=saved.querySelector('[data-location-state=expiring]');assert(getComputedStyle(orange.querySelector('td')).backgroundColor==='rgb(255, 240, 204)','Actual cells show orange, not hidden behind zebra stripes');document.documentElement.dataset.theme='dark';assert(getComputedStyle(orange.querySelector('td')).backgroundColor==='rgb(74, 52, 24)','Night mode uses readable orange cell backgrounds');online=false;const offline=document.createElement('section');document.body.append(offline);await KnowledgeInventory.mount({id:7},offline,'places');assert(offline.querySelectorAll('[data-knowledge-saved] tbody tr').length===4&&offline.querySelector('[data-location-save]').disabled,'Offline inventory readable, editing disabled');assert(document.documentElement.scrollWidth<=innerWidth+1,'Layout fits narrow tablet/phone');parent.postMessage({layoutStatus:'pass'},'*');})().catch(error=>parent.postMessage({layoutStatus:'fail',message:error.stack},'*'));
'''
    css='\n'.join((STATIC/name).read_text() for name in ['tf-portal.css','work-report.css','portal-theme.css','responsive.css'])
    return '<!doctype html><meta charset="utf-8"><style>'+css+'</style><main><section class="train-panel"><div id="inventory"></div></section></main><script>'+scripts+checks+'</script>'
if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--output-dir',required=True);args=parser.parse_args();check_pages(fixture,args.output_dir,label='Location knowledge editing')
